<?php require dirname(__DIR__).'/inc/page_helpers.php';moderator_required();
if(page_post()){check_csrf();$id=(int)($_POST['id']??0);$action=(string)($_POST['action']??'');$q=$db->prepare('SELECT * FROM moderation_reports WHERE id=?');$q->execute([$id]);$report=$q->fetch();if($report&&$report['status']==='pending'){
if(in_array($action,['resolved','dismissed'],true)){$db->prepare('UPDATE moderation_reports SET status=?,reviewed_by=?,reviewed_at=NOW() WHERE id=?')->execute([$action,$currentUser['id'],$id]);notice('Report updated.');}
elseif($action==='remove'){$type=$report['target_type'];$target=(int)$report['target_id'];$allowed=true;
if($type==='game')$db->prepare("UPDATE games SET status='hidden' WHERE id=?")->execute([$target]);
elseif($type==='user'){$q=$db->prepare('SELECT role FROM users WHERE id=?');$q->execute([$target]);$targetUser=$q->fetch();if(!$targetUser||$target===(int)$currentUser['id']||($currentUser['role']!=='admin'&&$targetUser['role']!=='user')){$allowed=false;}else{$db->prepare("UPDATE users SET account_status='banned' WHERE id=?")->execute([$target]);$db->prepare('INSERT INTO moderation_actions(moderator_id,target_user_id,action,note) VALUES(?,?,?,?)')->execute([$currentUser['id'],$target,'ban','Banned after report #'.$id]);}}
elseif($type==='item')$db->prepare('DELETE FROM catalog_items WHERE id=?')->execute([$target]);
elseif($type==='forum_topic')$db->prepare('DELETE FROM forum_topics WHERE id=?')->execute([$target]);
elseif($type==='forum_reply')$db->prepare('DELETE FROM forum_replies WHERE id=?')->execute([$target]);
if($allowed){$db->prepare("UPDATE moderation_reports SET status='resolved',reviewed_by=?,reviewed_at=NOW() WHERE id=?")->execute([$currentUser['id'],$id]);notice('Reported content moderated.');}else notice('You cannot moderate that account.','error');
}}go('/Admin/Reports.php');}
$reports=$db->query("SELECT r.*,u.username reporter FROM moderation_reports r JOIN users u ON u.id=r.reporter_id ORDER BY (r.status='pending') DESC,r.id DESC LIMIT 200")->fetchAll();page_start('Moderation Reports');?><section class="Panel"><h1>Moderation Reports</h1><?php foreach($reports as $r):?><article class="tile"><b>#<?=(int)$r['id']?> · <?=e($r['target_type'])?> #<?=(int)$r['target_id']?></b><p><?=nl2br(e($r['reason']))?></p><small>Reported by <?=e($r['reporter'])?> · <?=e($r['created_at'])?> · <?=e($r['status'])?></small><?php if($r['status']==='pending'):?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="id" value="<?=(int)$r['id']?>"><button name="action" value="resolved">Resolve</button> <button name="action" value="dismissed">Dismiss</button> <button name="action" value="remove">Remove / Moderate content</button></form><?php endif;?></article><?php endforeach;?><?php if(!$reports):?><p>No reports.</p><?php endif;?></section><?php page_end();?>